T4=[[1,1,0],[0,4,0],[0,1,5],[4,4,7]]  # template rows6-9 cols7-9
def solve(g,bg,marker,T,ar,ac):
    h,w=len(g),len(g[0]); o=[[bg]*w for _ in range(h)]
    # keep original template instance (non-bg, non-marker cells)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and g[r][c]!=marker: o[r][c]=g[r][c]
    TH,TW=len(T),len(T[0])
    contrib={}
    for r in range(h):
        for c in range(w):
            if g[r][c]==marker:
                for i in range(TH):
                    for j in range(TW):
                        rr,cc=r-ar+i,c-ac+j
                        if 0<=rr<h and 0<=cc<w:
                            if (rr,cc) in contrib and contrib[(rr,cc)]!=T[i][j]: print('CONFLICT',rr,cc,contrib[(rr,cc)],T[i][j])
                            contrib[(rr,cc)]=T[i][j]
    for (r,c),v in contrib.items(): o[r][c]=v
    return o
